```css
/* =========================================================
   A4 PAGE
========================================================= */

@page {
    size: A4;
    margin: 0;
}


/* =========================================================
   MAIN PRINT AREA
========================================================= */

html,
body {
    width: 100%;
    margin: 0 !important;
    padding: 0 !important;
}

.print-format {
    width: 210mm !important;
    min-height: 297mm !important;

    margin: 0 auto !important;
    padding: 7mm 12mm 10mm 12mm !important;

    box-sizing: border-box !important;

    font-family: Arial, Helvetica, sans-serif;
    font-size: 11.5px;
    line-height: 1.5;

    color: #000;
    background-color: #fff;
}

.consolidated-invoice {
    width: 100%;
    max-width: 100%;
    min-height: 280mm;

    margin: 0 auto;
    padding: 0;

    display: flex;
    flex-direction: column;

    box-sizing: border-box;
    color: #000;
}


/* =========================================================
   COMPANY HEADER IMAGE
   FULL IMAGE WITHOUT CROPPING
========================================================= */

.company-header {
    width: 100%;
    max-width: 100%;

    margin: 0 0 15px 0;
    padding: 0;

    text-align: center;

    box-sizing: border-box;
    page-break-inside: avoid;
    overflow: visible;
}

.company-header-image {
    display: block;

    width: 100%;
    max-width: 100%;
    height: auto;

    margin: 0 auto;
    padding: 0;

    object-fit: contain;
    object-position: center center;
}


/* =========================================================
   DOCUMENT TITLE
========================================================= */

.invoice-title {
    width: 100%;

    margin: 15px 0 6px 0;

    text-align: center;

    font-size: 19px;
    line-height: 1.2;
    font-weight: 700;
}

.branch-title {
    width: 100%;

    margin: 0 0 22px 0;

    text-align: center;

    font-size: 13px;
    line-height: 1.25;
    font-weight: 700;

    text-decoration: underline;
}


/* =========================================================
   BILL NUMBER AND LETTER DATE
========================================================= */

.bill-information {
    width: 100%;
    max-width: 100%;

    margin: 0 0 28px 0;
    padding: 0;

    border: none !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;

    table-layout: fixed;
    box-sizing: border-box;
}

.bill-information tbody,
.bill-information tr {
    width: 100%;

    margin: 0;
    padding: 0;

    border: none !important;
}

.bill-information td {
    width: 50%;

    margin: 0 !important;
    padding: 0 !important;

    border: none !important;

    font-size: 12px;
    line-height: 1.4;

    vertical-align: top;
    white-space: nowrap;
}

.bill-number {
    width: 50%;
    text-align: left !important;
}
.tpn-number {
    width: 50%;
    text-align: left !important;
}

.letter-date {
    width: 50%;
    text-align: right !important;
}
.gst-number {
    width: 50%;
    text-align: right !important;
}


/* =========================================================
   CUSTOMER DETAILS
========================================================= */

.customer-details {
    width: 100%;

    margin: 0 0 21px 0;
    padding: 0;

    box-sizing: border-box;

    font-size: 12px;
    line-height: 1.6;
}

.customer-details div {
    margin: 0;
    padding: 0;
}

.customer-name {
    font-weight: 400;
}

.customer-information-row {
    width: 100%;
}

.address-value {
    display: inline;
}

.address-value p,
.address-value div {
    display: inline;

    margin: 0 !important;
    padding: 0 !important;
}

.date-range {
    margin-top: 1px !important;
}

.date-separator {
    display: inline-block;
    width: 20px;
}


/* =========================================================
   SUBJECT AND REFERENCE
========================================================= */

.subject-reference-section {
    width: 100%;

    margin: 0 0 17px 0;
    padding: 0;

    box-sizing: border-box;

    font-size: 12px;
    line-height: 1.5;
}

.subject-line,
.reference-line {
    width: 100%;

    margin: 0;
    padding: 0;
}

.subject-line strong {
    font-weight: 700;
}


/* =========================================================
   SALUTATION
========================================================= */

.salutation {
    width: 100%;

    margin: 0 0 17px 0;
    padding: 0;

    box-sizing: border-box;

    font-size: 12px;
    line-height: 1.5;
}


/* =========================================================
   HEADER DESCRIPTION
========================================================= */

.invoice-header-content {
    width: 100%;

    margin: 0 0 15px 0;
    padding: 0;

    box-sizing: border-box;

    font-size: 12px;
    line-height: 1.55;

    overflow-wrap: break-word;
    word-wrap: break-word;
}

.invoice-header-content p {
    margin: 0 0 12px 0;
    padding: 0;
}

.invoice-header-content ul,
.invoice-header-content ol {
    margin-top: 5px;
    margin-bottom: 9px;
}


/* =========================================================
   INVOICE TABLE
========================================================= */

.invoice-details-table {
    width: 100%;
    max-width: 100%;

    margin: 5px 0 0 0;
    padding: 0;

    border-collapse: collapse;
    table-layout: fixed;

    box-sizing: border-box;
    page-break-inside: auto;
}

.invoice-details-table thead {
    display: table-header-group;
}

.invoice-details-table tr {
    page-break-inside: avoid;
    page-break-after: auto;
}

.invoice-details-table th,
.invoice-details-table td {
    border: 1px solid #bfc1c3;

    padding: 7px 5px;

    box-sizing: border-box;
    vertical-align: middle;

    overflow-wrap: break-word;
    word-wrap: break-word;
}

.invoice-details-table th {
    background-color: #eeeeee !important;

    font-size: 11px;
    line-height: 1.25;
    font-weight: 700;

    text-align: center;
    color: #000;
}

.invoice-details-table td {
    font-size: 11px;
    line-height: 1.35;
}


/* =========================================================
   TABLE COLUMN WIDTHS
========================================================= */

.column-number {
    width: 5%;
}

.column-gdn {
    width: 20%;
}

.column-quantity {
    width: 9%;
}

.column-goods {
    width: 12%;
}

.column-transportation {
    width: 12%;
}

.column-loading {
    width: 11%;
}

.column-challan {
    width: 10%;
}

.column-challan {
    width: 10%;
}

.column-amount {
    width: 10%;
}


/* =========================================================
   TABLE ALIGNMENT
========================================================= */

.text-center {
    text-align: center;
}

.text-right {
    text-align: right;
}

.no-data {
    padding: 11px !important;
    text-align: center;
}

.total-row td {
    padding-top: 8px;
    padding-bottom: 8px;
}

.total-label {
    text-align: center;
    font-weight: 700;
}

.total-value {
    text-align: right;
    font-weight: 400;
}


/* =========================================================
   AMOUNT IN WORDS
========================================================= */

.amount-in-words {
    width: 100%;

    margin: 17px 0 16px 0;
    padding: 0;

    box-sizing: border-box;

    font-size: 12px;
    line-height: 1.55;

    overflow-wrap: break-word;
    word-wrap: break-word;
}


/* =========================================================
   FOOTER CONTENT
========================================================= */

.invoice-footer-content {
    width: 100%;

    margin: 0;
    padding: 0;

    box-sizing: border-box;

    font-size: 12px;
    line-height: 1.55;
}

.invoice-footer-content p {
    margin: 0 0 15px 0;
    padding: 0;
}

.invoice-footer-content ul,
.invoice-footer-content ol {
    margin-top: 5px;
    margin-bottom: 9px;
}


/* =========================================================
   SIGNATURE SECTION
========================================================= */

.signature-space {
    height: 38px;
}

.signature-details {
    font-size: 12px;
    line-height: 1.4;
}


/* =========================================================
   BOTTOM LINE
========================================================= */

.bottom-line {
    width: 100%;

    /*
        Pushes the line and system note toward
        the bottom of the A4 page.
    */
    margin-top: auto;
    padding-top: 26px;

    border-bottom: 1px solid #9eacb2;

    box-sizing: border-box;
    page-break-inside: avoid;
}


/* =========================================================
   SYSTEM-GENERATED NOTE
========================================================= */

.system-note {
    width: 100%;

    margin: 10px 0 0 0;
    padding: 0;

    box-sizing: border-box;

    text-align: right;

    font-size: 10px;
    line-height: 1.4;

    color: #000;

    page-break-inside: avoid;
}


/* =========================================================
   RICH TEXT CLEANUP
========================================================= */

.invoice-header-content > :first-child,
.invoice-footer-content > :first-child {
    margin-top: 0 !important;
}

.invoice-header-content > :last-child,
.invoice-footer-content > :last-child {
    margin-bottom: 0 !important;
}

.invoice-header-content table,
.invoice-footer-content table {
    width: 100%;
    max-width: 100%;
}


/* =========================================================
   SCREEN PREVIEW
========================================================= */

@media screen {

    .print-format {
        margin-left: auto !important;
        margin-right: auto !important;
    }

    .consolidated-invoice {
        min-height: 280mm;
    }
}


/* =========================================================
   PRINT SETTINGS
========================================================= */

@media print {

    html,
    body {
        width: 100%;

        margin: 0 !important;
        padding: 0 !important;

        background-color: #fff !important;
    }

    .print-format {
        width: 210mm !important;
        min-height: 297mm !important;

        margin: 0 !important;
        padding: 7mm 12mm 10mm 12mm !important;

        box-sizing: border-box !important;
    }

    .consolidated-invoice {
        width: 100%;
        max-width: 100%;
        min-height: 280mm;

        margin: 0;
        padding: 0;

        display: flex;
        flex-direction: column;

        box-sizing: border-box;
    }

    .company-header {
        width: 100%;
        max-width: 100%;

        margin: 0 0 15px 0;
        padding: 0;

        overflow: visible;
        page-break-inside: avoid;
    }

    .company-header-image {
        display: block;

        width: 100%;
        max-width: 100%;
        height: auto;

        margin: 0 auto;
        padding: 0;

        object-fit: contain;
        object-position: center center;
    }

    .invoice-details-table {
        width: 100%;
        max-width: 100%;

        page-break-inside: auto;
    }

    .invoice-details-table th {
        background-color: #eeeeee !important;

        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }

    .invoice-details-table tr {
        page-break-inside: avoid;
    }

    .subject-reference-section,
    .salutation,
    .bottom-line,
    .system-note {
        page-break-inside: avoid;
    }
}
